@import "tailwindcss";

:root {
  --font-sans: var(--font-sans), system-ui, sans-serif;
  --font-serif: var(--font-serif), Georgia, serif;

  /* liquid glass tokens */
  --glass-bg: rgba(255, 255, 255, 0.12);
  --glass-bg-strong: rgba(255, 255, 255, 0.18);
  --glass-border: rgba(255, 255, 255, 0.35);
  --glass-highlight: rgba(255, 255, 255, 0.55);
  --glass-shadow: 0 8px 32px rgba(10, 40, 90, 0.22);

  --ink: #f4f9ff;
  --ink-dim: rgba(232, 242, 255, 0.72);
  --dark: #06182e;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  color: var(--ink);
  font-family: var(--font-sans);
  background: #04101f;
  overflow-x: hidden;
}

/* ------------------------------------------------------------------ */
/* Background video (your hero.mp4)                                    */
/* ------------------------------------------------------------------ */
.bg-video {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
}

.bg-tint {
  position: fixed;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(120% 80% at 15% 10%, rgba(4, 20, 45, 0.55), transparent 60%),
    linear-gradient(180deg, rgba(4, 16, 35, 0.35) 0%, rgba(4, 16, 35, 0.15) 40%, rgba(4, 16, 35, 0.55) 100%);
  pointer-events: none;
}

/* ------------------------------------------------------------------ */
/* Liquid glass primitive                                             */
/* ------------------------------------------------------------------ */
.glass {
  position: relative;
  background: var(--glass-bg);
  backdrop-filter: blur(18px) saturate(180%);
  -webkit-backdrop-filter: blur(18px) saturate(180%);
  border: 1px solid var(--glass-border);
  box-shadow:
    var(--glass-shadow),
    inset 0 1px 0 var(--glass-highlight),
    inset 0 -1px 1px rgba(0, 0, 0, 0.05);
}

.glass::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.25) 0%,
    rgba(255, 255, 255, 0.02) 40%,
    rgba(255, 255, 255, 0) 100%
  );
  pointer-events: none;
  opacity: 0.9;
}

/* ------------------------------------------------------------------ */
/* Nav                                                                */
/* ------------------------------------------------------------------ */
.nav {
  position: fixed;
  top: 18px;
  left: 50%;
  transform: translateX(-50%);
  width: min(1100px, calc(100% - 36px));
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px 10px 20px;
  border-radius: 999px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  letter-spacing: -0.02em;
  font-size: 18px;
}
.logo-mark {
  color: #bfe0ff;
  filter: drop-shadow(0 0 8px rgba(150, 200, 255, 0.6));
}

.nav-links {
  display: flex;
  gap: 28px;
  font-size: 14px;
  font-weight: 500;
}
.nav-links a {
  color: var(--ink-dim);
  text-decoration: none;
  transition: color 0.2s ease;
}
.nav-links a:hover {
  color: var(--ink);
}

@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
}

/* ------------------------------------------------------------------ */
/* Pills & buttons                                                    */
/* ------------------------------------------------------------------ */
.pill {
  border-radius: 999px;
  padding: 9px 18px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease;
}
.pill:hover {
  transform: translateY(-1px);
  background: var(--glass-bg-strong);
}

.label-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--ink-dim);
  cursor: default;
}
.label-pill.center {
  justify-content: center;
}
.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #7ee0a0;
  box-shadow: 0 0 8px #7ee0a0;
}

.btn {
  border: none;
  cursor: pointer;
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 600;
  padding: 13px 26px;
  border-radius: 999px;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
}
.btn:hover {
  transform: translateY(-2px);
}
.btn-dark {
  background: var(--dark);
  color: #eaf3ff;
  box-shadow: 0 10px 30px rgba(4, 20, 45, 0.45);
}
.btn-dark:hover {
  box-shadow: 0 14px 36px rgba(4, 20, 45, 0.6);
}
.btn-ghost {
  color: var(--ink);
  background: var(--glass-bg);
  border-radius: 999px;
}

/* ------------------------------------------------------------------ */
/* Stage + view transitions                                          */
/* ------------------------------------------------------------------ */
.stage {
  position: relative;
  min-height: 100dvh;
  width: 100%;
}

.view {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  padding: 120px 7vw 60px;
  opacity: 0;
  transform: translateY(18px) scale(0.99);
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.view.is-active {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

/* ------------------------------------------------------------------ */
/* Hero                                                               */
/* ------------------------------------------------------------------ */
.hero {
  max-width: 640px;
}
.hero .label-pill {
  margin-bottom: 26px;
}
.hero-title {
  font-size: clamp(44px, 6vw, 76px);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: -0.03em;
  margin: 0 0 22px;
}
.hero-title em {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.01em;
}
.hero-sub {
  font-size: 18px;
  line-height: 1.55;
  color: var(--ink-dim);
  max-width: 520px;
  margin: 0 0 34px;
}
.hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

/* ------------------------------------------------------------------ */
/* Search view                                                        */
/* ------------------------------------------------------------------ */
.view-search {
  justify-content: center;
}
.search-wrap {
  width: min(760px, 100%);
  text-align: center;
}
.search-wrap .label-pill {
  margin-bottom: 24px;
}
.search-title {
  font-size: clamp(38px, 5vw, 60px);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin: 0 0 34px;
}
.search-title em {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
}
.search-box {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 22px;
  border-radius: 999px;
}
.search-icon {
  font-size: 18px;
  opacity: 0.8;
}
#search-input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 17px;
  padding: 12px 4px;
}
#search-input::placeholder {
  color: rgba(232, 242, 255, 0.5);
}
.search-go {
  white-space: nowrap;
}
.chips {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
  margin-top: 22px;
}
.chip {
  border-radius: 999px;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease;
}
.chip:hover {
  transform: translateY(-2px);
  background: var(--glass-bg-strong);
}

/* ------------------------------------------------------------------ */
/* Results view                                                       */
/* ------------------------------------------------------------------ */
.view-results {
  align-items: flex-start;
  overflow-y: auto;
  padding-top: 100px;
}
.results-wrap {
  width: min(880px, 100%);
  margin: 0 auto;
}
.back-btn {
  display: inline-flex;
  margin-bottom: 22px;
  border-radius: 999px;
}
.recipe-head {
  margin-bottom: 8px;
}
.recipe-kicker {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-dim);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.recipe-title {
  font-size: clamp(30px, 4vw, 44px);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin: 6px 0 6px;
}
.recipe-title em {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
}
.recipe-meta {
  color: var(--ink-dim);
  font-size: 15px;
  margin-bottom: 26px;
}

.step {
  border-radius: 20px;
  padding: 20px 22px;
  margin-bottom: 14px;
}
.step-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}
.step-name {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 600;
  font-size: 17px;
}
.step-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.16);
  font-size: 13px;
  font-weight: 700;
}
.freq {
  font-size: 12px;
  font-weight: 700;
  padding: 5px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.freq-high {
  background: rgba(126, 224, 160, 0.2);
  color: #b7f5cd;
  border: 1px solid rgba(126, 224, 160, 0.35);
}
.freq-warn {
  background: rgba(255, 209, 102, 0.16);
  color: #ffe1a3;
  border: 1px solid rgba(255, 209, 102, 0.3);
}
.step code {
  display: block;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 13.5px;
  line-height: 1.6;
  background: rgba(3, 12, 28, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 12px 14px;
  margin: 8px 0 12px;
  color: #d7e8ff;
  white-space: pre-wrap;
  overflow-x: auto;
}
.step-note {
  font-size: 14px;
  color: var(--ink-dim);
  margin-bottom: 10px;
}
.receipts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.receipt {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
  color: #bcd8ff;
  text-decoration: none;
  padding: 5px 10px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  transition: background 0.15s ease, transform 0.15s ease;
}
.receipt:hover {
  background: rgba(255, 255, 255, 0.16);
  transform: translateY(-1px);
}
.receipt::after {
  content: " ↗";
  opacity: 0.6;
}

.verify-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  border-radius: 16px;
  padding: 14px 18px;
  margin-bottom: 22px;
  font-size: 14px;
  color: #d7f0ff;
}
.verify-banner b {
  color: #fff;
}

.empty {
  text-align: center;
  color: var(--ink-dim);
  padding: 40px;
}

