"use client";

import { useState } from "react";
import { findRecipe, type Recipe } from "@/lib/recipes";

type View = "hero" | "search" | "results";

const CHIPS = [
  { emoji: "✍️", label: "collab editor", q: "collaborative rich-text editor with comments" },
  { emoji: "🗂️", label: "kanban board", q: "drag and drop kanban board" },
  { emoji: "📊", label: "data grid", q: "data table with sorting and filtering" },
  { emoji: "🔐", label: "auth flow", q: "authentication with email and oauth" },
];

export default function Home() {
  const [view, setView] = useState<View>("hero");
  const [query, setQuery] = useState("");
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [notFound, setNotFound] = useState(false);

  function runSearch(q: string) {
    const found = findRecipe(q);
    setRecipe(found);
    setNotFound(!found);
    setView("results");
  }

  function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (query.trim()) runSearch(query);
  }

  return (
    <>
      <video className="bg-video" autoPlay muted loop playsInline>
        <source src="/hero.mp4" type="video/mp4" />
      </video>
      <div className="bg-tint" />

      {/* Nav */}
      <nav className="glass nav">
        <div className="nav-logo">
          <span className="logo-mark">◆</span> recipe
        </div>
        <div className="nav-links">
          <a onClick={() => setView("hero")}>How it works</a>
          <a onClick={() => setView("search")}>Recipes</a>
          <a>Repos</a>
          <a>Docs</a>
        </div>
        <button className="glass pill" onClick={() => setView("search")}>
          Start
        </button>
      </nav>

      <main className="stage">
        {/* HERO */}
        <section className={`view view-hero ${view === "hero" ? "is-active" : ""}`}>
          <div className="hero">
            <div className="glass pill label-pill">
              <span className="dot" /> Powered by Entire Graph
            </div>
            <h1 className="hero-title">
              Ship features with
              <br />
              <em>libraries that fit</em>
            </h1>
            <p className="hero-sub">
              Describe what you&apos;re building. Get a proven, cited
              integration recipe — mined from how real open-source repositories
              actually wire the library together.
            </p>
            <div className="hero-actions">
              <button className="btn btn-dark" onClick={() => setView("search")}>
                Start a project
              </button>
              <button className="btn btn-ghost glass" onClick={() => setView("search")}>
                See how it works
              </button>
            </div>
          </div>
        </section>

        {/* SEARCH */}
        <section className={`view view-search ${view === "search" ? "is-active" : ""}`}>
          <div className="search-wrap">
            <div className="glass pill label-pill center">
              <span className="dot" /> mined from real repositories
            </div>
            <h2 className="search-title">
              What are you <em>building?</em>
            </h2>
            <form className="glass search-box" onSubmit={onSubmit}>
              <span className="search-icon">🔍</span>
              <input
                id="search-input"
                autoComplete="off"
                placeholder="collaborative rich-text editor with comments…"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
              <button type="submit" className="btn btn-dark search-go">
                Find recipe
              </button>
            </form>
            <div className="chips">
              {CHIPS.map((c) => (
                <button
                  key={c.label}
                  className="glass chip"
                  onClick={() => {
                    setQuery(c.q);
                    runSearch(c.q);
                  }}
                >
                  {c.emoji} {c.label}
                </button>
              ))}
            </div>
          </div>
        </section>

        {/* RESULTS */}
        <section className={`view view-results ${view === "results" ? "is-active" : ""}`}>
          <div className="results-wrap">
            <button className="glass pill back-btn" onClick={() => setView("search")}>
              ← new search
            </button>
            {recipe ? <RecipeView recipe={recipe} /> : null}
            {notFound ? (
              <div className="glass empty" style={{ borderRadius: 20 }}>
                No mined recipe for that yet. Try “collab editor”, “kanban
                board”, “data grid”, or “auth flow”.
              </div>
            ) : null}
          </div>
        </section>
      </main>
    </>
  );
}

function RecipeView({ recipe }: { recipe: Recipe }) {
  return (
    <div>
      <div className="recipe-head">
        <span className="recipe-kicker">Recipe · {recipe.library}</span>
        <h2 className="recipe-title">
          {recipe.title} <em>{recipe.emphasis}</em>
        </h2>
        <p className="recipe-meta">
          Mined from {recipe.reposMined} repositories · {recipe.callSites} call
          sites · runners-up: {recipe.runnersUp}
        </p>
      </div>

      <div className="glass verify-banner" style={{ borderRadius: 16 }}>
        ✅{" "}
        <span>
          Every step below is <b>graph-verified</b> against real call sites —
          click any receipt to inspect the source. No guesses.
        </span>
      </div>

      {recipe.steps.map((step, i) => (
        <div key={step.name} className="glass step">
          <div className="step-head">
            <div className="step-name">
              <span className="step-num">{i + 1}</span>
              {step.name}
            </div>
            <span className={`freq ${step.level === "high" ? "freq-high" : "freq-warn"}`}>
              {step.level === "high" ? "✓ " : "⚠ "}
              {step.freq} repos
            </span>
          </div>
          {step.code ? <code>{step.code}</code> : null}
          {step.note ? <p className="step-note">{step.note}</p> : null}
          <div className="receipts">
            {step.receipts.map((r) => (
              <a
                key={r.label}
                className="receipt"
                href={r.url}
                target="_blank"
                rel="noreferrer"
              >
                {r.label}
              </a>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

