  gap: 10px;
  cursor: pointer;
}
.nav-logo svg {
  display: block;
}
.nav-wordmark {
  font-weight: 700;
  font-size: 18px;
  letter-spacing: -0.02em;
  color: var(--ink);
}

.nav-links {
  display: flex;
  gap: 26px;
  font-size: 14px;
  font-weight: 500;
}
.nav-links a {
  color: var(--ink-dim);
  text-decoration: none;
  cursor: pointer;
  transition: color 0.2s ease;
}
.nav-links a:hover {
  color: var(--ink);
}

.pill-contact {
  background: var(--dark);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 10px 22px;
  font-family: var(--font-sans);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.2s ease;
  box-shadow: 0 6px 18px rgba(13, 31, 51, 0.22);
}
.pill-contact:hover {
  transform: translateY(-1px);
}

@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
}

/* ------------------------------------------------------------------ */
/* Pills & buttons                                                    */
/* ------------------------------------------------------------------ */
.pill {
  border-radius: 999px;
  padding: 9px 18px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease;
}
.pill:hover {
  transform: translateY(-1px);
  background: var(--glass-bg-strong);
}

.label-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 15px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--ink-dim);
  cursor: default;
}
.label-pill.center {
  justify-content: center;
}
.label-pill .diamond {
  color: var(--accent);
  font-size: 10px;
}
.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 8px rgba(47, 158, 95, 0.7);
}

.btn {
  border: none;
  cursor: pointer;
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 600;
  padding: 13px 26px;
  border-radius: 999px;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
}
.btn:hover {
  transform: translateY(-2px);
}
.btn-dark {
  background: var(--dark);
  color: #eaf3ff;
  box-shadow: 0 12px 30px rgba(13, 31, 51, 0.28);
}
.btn-dark:hover {
  box-shadow: 0 16px 38px rgba(13, 31, 51, 0.38);
}
.btn-ghost {
  color: var(--ink);
  background: var(--glass-bg);
  border-radius: 999px;
}

.btn-icon {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding-right: 8px;
}
.btn-circle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: #eaf3ff;
  color: #0d1f33;
  font-size: 14px;
  font-weight: 700;
}
.btn-text {
  background: transparent;
  border: none;
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  padding: 13px 18px;
  border-radius: 999px;
  transition: color 0.2s ease, transform 0.15s ease;
}
.btn-text:hover {
  transform: translateY(-2px);
  opacity: 0.7;
}

/* ------------------------------------------------------------------ */
/* Stage + view transitions                                          */
/* ------------------------------------------------------------------ */
.stage {
  position: relative;
  min-height: 100dvh;
  width: 100%;
}

.view {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  padding: 120px 7vw 60px;
  opacity: 0;
  transform: translateY(18px) scale(0.99);
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.view.is-active {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

/* ------------------------------------------------------------------ */
/* Hero                                                               */
/* ------------------------------------------------------------------ */
.hero {
  max-width: 640px;
}
.hero .label-pill {
  margin-bottom: 26px;
}
.hero-title {
  font-size: clamp(46px, 6.4vw, 82px);
  font-weight: 800;
  line-height: 0.98;
  letter-spacing: -0.045em;
  margin: 0 0 22px;
  color: var(--ink);
}
.hero-title em {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.01em;
}
.hero-sub {
  font-size: 18px;
  line-height: 1.55;
  color: var(--ink-dim);
  max-width: 500px;
  margin: 0 0 34px;
}
.hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: center;
}

/* ------------------------------------------------------------------ */
/* Search view                                                        */
/* ------------------------------------------------------------------ */
.view-search {
  justify-content: center;
}
.search-wrap {
  width: min(760px, 100%);
  text-align: center;
}
.search-wrap .label-pill {
  margin-bottom: 24px;
}
.search-title {
  font-size: clamp(38px, 5vw, 60px);
  font-weight: 800;
  letter-spacing: -0.035em;
  margin: 0 0 34px;
  color: var(--ink);
}
.search-title em {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
}
.search-box {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 22px;
  border-radius: 999px;
}
.search-icon {
  font-size: 18px;
  opacity: 0.7;
}
#search-input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 17px;
  padding: 12px 4px;
}
#search-input::placeholder {
  color: rgba(13, 31, 51, 0.42);
}
.search-go {
  white-space: nowrap;
}
.chips {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
  margin-top: 22px;
}
.chip {
  border-radius: 999px;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease;
}
.chip:hover {
  transform: translateY(-2px);
  background: var(--glass-bg-strong);
}

/* ------------------------------------------------------------------ */
/* Results view                                                       */
/* ------------------------------------------------------------------ */
.view-results {
  align-items: flex-start;
  overflow-y: auto;
  padding-top: 100px;
}
.results-wrap {
  width: min(880px, 100%);
  margin: 0 auto;
}
.back-btn {
  display: inline-flex;
  margin-bottom: 22px;
  border-radius: 999px;
}
.recipe-head {
  margin-bottom: 8px;
}
.recipe-kicker {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink-dim);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.recipe-title {
  font-size: clamp(30px, 4vw, 44px);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 6px 0 6px;
  color: var(--ink);
}
.recipe-title em {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 400;
}
.recipe-meta {
  color: var(--ink-dim);
  font-size: 15px;
  margin-bottom: 26px;
}

.step {
  border-radius: 20px;
  padding: 20px 22px;
  margin-bottom: 14px;
}
.step-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}
.step-name {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 700;
  font-size: 17px;
  color: var(--ink);
}
.step-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: rgba(13, 31, 51, 0.1);
  font-size: 13px;
  font-weight: 700;
}
.freq {
  font-size: 12px;
  font-weight: 700;
  padding: 5px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.freq-high {
  background: rgba(47, 158, 95, 0.14);
  color: #1f7a47;
  border: 1px solid rgba(47, 158, 95, 0.3);
}
.freq-warn {
  background: rgba(214, 158, 46, 0.16);
  color: #9a6b12;
  border: 1px solid rgba(214, 158, 46, 0.32);
}
.step code {
  display: block;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 13.5px;
  line-height: 1.6;
  background: #0d1f33;
  border-radius: 12px;
  padding: 12px 14px;
  margin: 8px 0 12px;
  color: #d7e8ff;
  white-space: pre-wrap;
  overflow-x: auto;
}
.step-note {
  font-size: 14px;
  color: var(--ink-dim);
  margin-bottom: 10px;
}
.receipts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.receipt {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 12px;
  color: #1a4a7a;
  text-decoration: none;
  padding: 5px 10px;
  border-radius: 8px;
  background: rgba(13, 31, 51, 0.06);
  border: 1px solid rgba(13, 31, 51, 0.12);
  transition: background 0.15s ease, transform 0.15s ease;
}
.receipt:hover {
  background: rgba(13, 31, 51, 0.12);
  transform: translateY(-1px);
}
.receipt::after {
  content: " ↗";
  opacity: 0.6;
}

.verify-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  border-radius: 16px;
  padding: 14px 18px;
  margin-bottom: 22px;
  font-size: 14px;
  color: var(--ink);
}
.verify-banner b {
  color: #1f7a47;
}

.empty {
  text-align: center;
  color: var(--ink-dim);
  padding: 40px;
}

