import { findRecipe } from "@/lib/recipes";

// Public query endpoint for web-direct users and other tools/agents:
//   GET /api/recipe?q=collaborative%20editor
// Returns the mined integration recipe (with real file:line receipts) as JSON.
export function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const q = searchParams.get("q") ?? "";

  if (!q.trim()) {
    return Response.json(
      { error: "missing query", usage: "/api/recipe?q=collaborative+editor" },
      { status: 400 }
    );
  }

  const recipe = findRecipe(q);
  if (!recipe) {
    return Response.json(
      { error: "no recipe found for that query", query: q },
      { status: 404 }
    );
  }

  return Response.json(recipe, {
    headers: { "cache-control": "public, max-age=60" },
  });
}

