// Goal-driven, on-demand recipe generation — the real skill.
//
//   node engine/cli.mjs generate "realtime collaborative editor"
//
// No hardcoded libraries. Given only an end goal it:
//   1. DISCOVERS real repos for the goal via `gh search repos`
//   2. RESOLVES the library by tallying the dominant dependency across them
//   3. MINES them with `entire graph edges`
//   4. DERIVES the playbook from the graph: top imported packages (install) +
//      top called/constructed library APIs (wiring), each with real receipts
//      and a real source line read from the cloned repo.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { edges, importedModule } from "./graph.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const CACHE = join(__dirname, ".cache");
const OUT = join(ROOT, "lib", "recipes.generated.json");

const MAX_REPOS = 4;
const MAX_REPO_KB = 90_000; // skip anything bigger than ~90MB shallow

// framework / stdlib noise to exclude when resolving the library + APIs
const PKG_DENY = new Set([
  "react", "react-dom", "next", "vue", "svelte", "typescript", "vite",
  "webpack", "eslint", "prettier", "tailwindcss", "@types/node", "@types/react",
  "@types/react-dom", "zod", "clsx", "classnames", "dotenv", "express",
  "@vitejs/plugin-react", "postcss", "autoprefixer",
]);
const SYM_DENY = new Set([
  "useState", "useEffect", "useRef", "useMemo", "useCallback", "useContext",
  "useReducer", "useLayoutEffect", "useImperativeHandle", "useId",
  "useRouter", "useSearchParams", "usePathname",
]);

const sh = (cmd, args) =>
  execFileSync(cmd, args, { encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });
const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
const repoName = (url) => url.replace(/\.git$/, "").split("/").pop();
const basePkg = (m) =>
  m.startsWith("@") ? m.split("/").slice(0, 2).join("/") : m.split("/")[0];

// ---- 1. discover -----------------------------------------------------------
function discoverRepos(goal) {
  console.log(`  discovering repos for "${goal}" via gh …`);
  let rows = [];
  try {
    const out = sh("gh", [
      "search", "repos", goal,
      "--language", "typescript", "--sort", "stars", "--limit", "12",
      "--json", "fullName,url",
    ]);
    rows = JSON.parse(out);
  } catch (e) {
    console.warn("  ! gh search failed:", e.message.split("\n")[0]);
  }
  const picked = [];
  for (const r of rows) {
    if (picked.length >= MAX_REPOS) break;
    let kb = 0;
    try {
      kb = parseInt(sh("gh", ["api", `repos/${r.fullName}`, "--jq", ".size"]).trim(), 10);
    } catch {}
    if (kb && kb > MAX_REPO_KB) {
      console.log(`    skip ${r.fullName} (${Math.round(kb / 1000)}MB)`);
      continue;
    }
    picked.push(r.url);
  }
  return picked;
}

function clone(url) {
  const dest = join(CACHE, repoName(url));
  if (existsSync(join(dest, ".git"))) return dest;
  mkdirSync(CACHE, { recursive: true });
  console.log(`  cloning ${url} …`);
  try {
    execFileSync("git", ["clone", "--depth", "1", "--single-branch", url, dest], {
      stdio: ["ignore", "ignore", "ignore"], timeout: 180000,
    });
    return dest;
  } catch {
    return null;
  }
}

// ---- helpers ---------------------------------------------------------------
function receipt(repo, url, file, line) {
  return {
    label: `${repo}/${file}${line ? `:${line}` : ""}`,
    url: `${url}/blob/HEAD/${file}${line ? `#L${line}` : ""}`,
  };
}
function snippet(repoPath, file, line) {
  if (!file || !line) return null;
  try {
    const lines = readFileSync(join(repoPath, file), "utf8").split("\n");
    return (lines[line - 1] || "").trim().slice(0, 160);
  } catch {
    return null;
  }
}

// ---- main ------------------------------------------------------------------
export function generate(goal, opts = {}) {
  const repoUrls = (opts.repos && opts.repos.length ? opts.repos : discoverRepos(goal));
  const repos = repoUrls
    .map((url) => {
      const path = clone(url);
      return path ? { url, path, name: repoName(url) } : null;
    })
    .filter(Boolean);

  if (!repos.length) throw new Error("no repos could be discovered/cloned for this goal");

  for (const r of repos) {
    console.log(`  graphing ${r.name} …`);
    r.imports = edges(r.path, ["IMPORTS"]);
    r.calls = edges(r.path, ["CALLS", "CONSTRUCTS"]);
  }
  const total = repos.length;

  // 2. resolve library: dominant external package across repos
  const pkgRepos = new Map(); // basePkg -> Set(repo)
  const pkgReceipt = new Map();
  for (const r of repos) {
    const seen = new Set();
    for (const rec of r.imports) {
      const mod = importedModule(rec);
      if (!mod || mod.startsWith(".") || mod.startsWith("external:import:.")) continue;
      const base = basePkg(mod);
      if (PKG_DENY.has(base)) continue;
      if (!pkgRepos.has(base)) pkgRepos.set(base, new Set());
      pkgRepos.get(base).add(r.name);
      const ev = rec.evidence && rec.evidence[0];
      const k = `${base}:${r.name}`;
      if (ev?.file_path && !pkgReceipt.has(base) && !seen.has(k)) {
        pkgReceipt.set(base, receipt(r.name, r.url, ev.file_path, ev.start_line));
        seen.add(k);
      }
    }
  }
  const rankedPkgs = [...pkgRepos.entries()].sort((a, b) => b[1].size - a[1].size);
  const library = opts.package || (rankedPkgs[0] && rankedPkgs[0][0]) || "unknown";
  // the library "family": packages sharing the resolved scope/name
  const famPrefix = library.startsWith("@") ? library.split("/")[0] : library;
  const family = rankedPkgs.filter(
    ([p]) => p === library || p.startsWith(famPrefix)
  );

  // 3+4. build steps from the graph
  const steps = [];

  // Install step
  const installPkgs = family.map(([p]) => p);
  steps.push({
    name: "Install",
    freq: `${Math.max(...family.map(([, s]) => s.size))}/${total}`,
    level: "high",
    code: `npm i ${installPkgs.join(" ")}`,
    note: `Packages the discovered repos import together. Most common: ${family
      .slice(0, 3)
      .map(([p, s]) => `${p} (${s.size}/${total})`)
      .join(", ")}.`,
    receipts: family.map(([p]) => pkgReceipt.get(p)).filter(Boolean).slice(0, 4),
  });

  // API steps: rank called/constructed library-ish symbols
  const symRepos = new Map(); // symbol -> Set(repo)
  const symReceipts = new Map(); // symbol -> [receipt]
  const symSnippet = new Map();
  for (const r of repos) {
    for (const rec of r.calls) {
      const ev = rec.evidence && rec.evidence[0];
      const raw = ev?.detail || (rec.to_id ? rec.to_id.split(":").pop() : "");
      const name = (raw || "").split(/[^A-Za-z0-9_$]+/).filter(Boolean).pop();
      if (!name || name.length < 3 || SYM_DENY.has(name)) continue;
      // library-API heuristic: Constructors/Components (Cap) or hooks (useX)
      if (!/^[A-Z]/.test(name) && !/^use[A-Z]/.test(name)) continue;
      if (!symRepos.has(name)) {
        symRepos.set(name, new Set());
        symReceipts.set(name, []);
      }
      symRepos.get(name).add(r.name);
      const arr = symReceipts.get(name);
      const key = `${r.name}:${ev?.file_path}:${ev?.start_line}`;
      if (ev?.file_path && arr.length < 4 && !arr.some((x) => x._k === key)) {
        arr.push({ ...receipt(r.name, r.url, ev.file_path, ev.start_line), _k: key });
        if (!symSnippet.has(name)) {
          const sn = snippet(r.path, ev.file_path, ev.start_line);
          if (sn) symSnippet.set(name, sn);
        }
      }
    }
  }
  const rankedSyms = [...symRepos.entries()]
    .sort((a, b) => b[1].size - a[1].size)
    .slice(0, 5);

  let callSites = installPkgs.length;
  for (const [name, set] of rankedSyms) {
    const receipts = (symReceipts.get(name) || []).map(({ _k, ...r }) => r);
    callSites += receipts.length;
    steps.push({
      name,
      freq: `${set.size}/${total}`,
      level: set.size >= Math.ceil(total / 2) ? "high" : "warn",
      code: symSnippet.get(name) || `${name}(…)`,
      note: `A ${library} API used across ${set.size}/${total} discovered repos.`,
      receipts,
    });
  }

  return {
    id: slug(goal),
    library,
    title: goal.charAt(0).toUpperCase() + goal.slice(1),
    emphasis: "",
    reposMined: total,
    callSites,
    runnersUp: rankedPkgs.slice(1, 4).map(([p]) => p).join(", ") || "—",
    keywords: [goal.toLowerCase(), ...goal.toLowerCase().split(/\s+/)],
    steps,
    sources: repos.map((r) => r.url),
  };
}

// persist into the corpus (mined recipes win)
export function saveRecipe(recipe) {
  let all = [];
  try {
    all = JSON.parse(readFileSync(OUT, "utf8"));
  } catch {}
  all = all.filter((r) => r.id !== recipe.id);
  all.push(recipe);
  writeFileSync(OUT, JSON.stringify(all, null, 2));
}

