import { spawnSync } from "node:child_process";
import { findRecipe } from "@/lib/recipes";

export const dynamic = "force-dynamic";
export const maxDuration = 300;

// Public query endpoint.
//   GET /api/recipe?q=collaborative+editor          corpus-first (instant)
//   GET /api/recipe?q=...&live=1                     mine on-demand if not in corpus
//
// The live path runs the entire-graph engine (discover repos → mine → derive),
// so it can take 30–120s. Without live=1 a miss returns 404 immediately.
export function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const q = searchParams.get("q") ?? "";
  const live = searchParams.get("live") === "1";

  if (!q.trim()) {
    return Response.json(
      { error: "missing query", usage: "/api/recipe?q=collaborative+editor" },
      { status: 400 }
    );
  }

  // 1. corpus-first (mined + hand-authored) — instant
  const hit = findRecipe(q);
  if (hit) {
    return Response.json({ ...hit, source: "corpus" });
  }

  // 2. no corpus hit
  if (!live) {
    return Response.json(
      {
        error: "not in corpus",
        query: q,
        hint: "retry with &live=1 to mine it on-demand with entire-graph",
      },
      { status: 404 }
    );
  }

  // 3. live: run the engine (discover → mine → derive) and return the playbook
  const res = spawnSync(
    "node",
    ["engine/cli.mjs", "generate", q, "--json"],
    {
      cwd: process.cwd(),
      encoding: "utf8",
      timeout: 240000,
      maxBuffer: 64 * 1024 * 1024,
      env: { ...process.env, PATH: `${process.env.HOME}/.local/bin:${process.env.PATH}` },
    }
  );

  if (res.status !== 0 || !res.stdout?.trim()) {
    return Response.json(
      { error: "generation failed", query: q, detail: (res.stderr || "").split("\n").slice(-3).join("\n") },
      { status: 502 }
    );
  }

  try {
    const recipe = JSON.parse(res.stdout);
    return Response.json({ ...recipe, source: "live" });
  } catch {
    return Response.json({ error: "could not parse engine output", query: q }, { status: 502 });
  }
}

