// Databricks-backed recipe corpus — the lakehouse serving layer.
// Reads/writes workspace.recipe.recipes via the SQL Statement Execution API.
// If the DATABRICKS_* env vars are absent, corpusEnabled() is false and the
// API route falls back to the local JSON corpus.
import type { Recipe } from "./recipes";

const HOST = process.env.DATABRICKS_HOST;
const TOKEN = process.env.DATABRICKS_TOKEN;
const WAREHOUSE = process.env.DATABRICKS_WAREHOUSE_ID;
const CATALOG = process.env.DATABRICKS_CATALOG || "workspace";
const SCHEMA = process.env.DATABRICKS_SCHEMA || "recipe";
const TABLE = `${CATALOG}.${SCHEMA}.recipes`;

export function corpusEnabled(): boolean {
  return Boolean(HOST && TOKEN && WAREHOUSE);
}

async function exec(statement: string) {
  const res = await fetch(`${HOST}/api/2.0/sql/statements`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      warehouse_id: WAREHOUSE,
      statement,
      wait_timeout: "30s",
    }),
  });
  const json = await res.json();
  if (json.status?.state !== "SUCCEEDED") {
    throw new Error(json.status?.error?.message || "databricks query failed");
  }
  return json;
}

const q = (s: string) => `'${String(s ?? "").replace(/'/g, "''")}'`;
const arr = (a: string[]) => `array(${(a || []).map(q).join(", ")})`;
const asArray = (v: unknown): string[] => {
  try {
    return Array.isArray(v) ? (v as string[]) : JSON.parse(v as string);
  } catch {
    return [];
  }
};
const asJson = (v: unknown) => {
  try {
    return typeof v === "string" ? JSON.parse(v) : v;
  } catch {
    return [];
  }
};

function rowToRecipe(row: string[]): Recipe {
  const [id, library, title, emphasis, repos, calls, runnersUp, keywords, steps, sources] = row;
  return {
    id,
    library,
    title,
    emphasis: emphasis || "",
    reposMined: Number(repos) || 0,
    callSites: Number(calls) || 0,
    runnersUp: runnersUp || "",
    keywords: asArray(keywords),
    steps: asJson(steps),
    sources: asArray(sources),
  } as Recipe;
}

export async function getAllRecipes(): Promise<Recipe[]> {
  const r = await exec(
    `SELECT id, library, title, emphasis, repos_mined, call_sites, runners_up, keywords, steps, sources FROM ${TABLE}`
  );
  return (r.result?.data_array || []).map(rowToRecipe);
}

// same keyword scoring as the local findRecipe, over the lakehouse rows
export async function queryRecipe(query: string): Promise<Recipe | null> {
  const qq = query.toLowerCase().trim();
  if (!qq) return null;
  let best: Recipe | null = null;
  let score = 0;
  for (const r of await getAllRecipes()) {
    let s = 0;
    for (const kw of r.keywords || []) if (qq.includes(kw)) s += kw.length;
    if (s > score) {
      score = s;
      best = r;
    }
  }
  return best;
}

// write-back: upsert a freshly-generated recipe into the lakehouse
export async function saveRecipe(r: Recipe & { sources?: string[] }): Promise<void> {
  await exec(`DELETE FROM ${TABLE} WHERE id = ${q(r.id)}`);
  await exec(
    `INSERT INTO ${TABLE} VALUES (${q(r.id)}, ${q(r.library)}, ${q(r.title)}, ` +
      `${q(r.emphasis || "")}, ${r.reposMined || 0}, ${r.callSites || 0}, ${q(r.runnersUp || "")}, ` +
      `${arr(r.keywords)}, ${q(JSON.stringify(r.steps || []))}, ${arr(r.sources || [])}, 'live', current_timestamp())`
  );
}

"use client";

import { useState } from "react";
import { findRecipe, type Recipe } from "@/lib/recipes";

type View = "hero" | "search" | "results";

const CHIPS = [
  { emoji: "✍️", label: "collab editor", q: "collaborative rich-text editor with comments" },
  { emoji: "🗂️", label: "kanban board", q: "drag and drop kanban board" },
  { emoji: "📊", label: "data grid", q: "data table with sorting and filtering" },
  { emoji: "🔐", label: "auth flow", q: "authentication with email and oauth" },
];

export default function Home() {
  const [view, setView] = useState<View>("hero");
  const [query, setQuery] = useState("");
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [notFound, setNotFound] = useState(false);

  function runSearch(q: string) {
    const found = findRecipe(q);
    setRecipe(found);
    setNotFound(!found);
    setView("results");
  }

  function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (query.trim()) runSearch(query);
  }

  return (
    <>
      {/* Liquid-glass refraction filter (feTurbulence -> feDisplacementMap),
          the CSS-native equivalent of dashersw/liquid-glass-js's WebGL warp */}
      <svg
        aria-hidden
        style={{ position: "absolute", width: 0, height: 0 }}
      >
        <filter id="liquid-glass" x="-20%" y="-20%" width="140%" height="140%">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.009 0.011"
            numOctaves={2}
            seed={42}
            result="noise"
          />
          <feGaussianBlur in="noise" stdDeviation={2} result="blurred" />
          <feDisplacementMap
            in="SourceGraphic"
            in2="blurred"
            scale={38}
            xChannelSelector="R"
            yChannelSelector="G"
          />
        </filter>
      </svg>

      <div className="bg-image" />
      <div className="bg-tint" />

      {/* Nav — compact centered glass pill */}
      <nav className="glass nav">
        <div className="nav-logo" onClick={() => setView("hero")}>
          <svg width="34" height="20" viewBox="0 0 34 20" aria-label="logo">
            <path d="M2 1h7a9 9 0 0 1 0 18H2z" fill="#0d1f33" />
            <path d="M15 1h7a9 9 0 0 1 0 18h-7z" fill="#0d1f33" />
          </svg>
          <span className="nav-wordmark">recipe</span>
        </div>
        <div className="nav-links">
          <a onClick={() => setView("hero")}>How it works</a>
          <a onClick={() => setView("search")}>Recipes</a>
          <a onClick={() => setView("search")}>Repositories</a>
          <a href="/docs">Docs</a>
        </div>
        <button className="pill-contact" onClick={() => setView("search")}>
          Find a recipe
        </button>
      </nav>

      <main className="stage">
        {/* HERO */}
        <section className={`view view-hero ${view === "hero" ? "is-active" : ""}`}>
          <div className="hero">
            <div className="glass pill label-pill">
              <span className="diamond">◆</span> Powered by Entire Graph
            </div>
            <h1 className="hero-title">
              Integrate any library
              <br />
              <em>the way real repos do</em>
            </h1>
            <p className="hero-sub">
              Describe what you&apos;re building and get a proven, cited recipe —
              mined from how real repos wire it together. Search it on the web, or
              download the skill so your coding agent pulls recipes mid-task.
            </p>
            <div className="hero-actions">
              <button
                className="btn btn-dark btn-icon"
                onClick={() => setView("search")}
              >
                Find a recipe
                <span className="btn-circle">↗</span>
              </button>
              <a
                className="btn btn-ghost glass"
                href="/recipe-finder-skill.zip"
                download
              >
                ↓ Download skill
              </a>
            </div>
          </div>
        </section>

        {/* SEARCH */}
        <section className={`view view-search ${view === "search" ? "is-active" : ""}`}>
          <div className="search-wrap">
            <div className="glass pill label-pill center">
              <span className="dot" /> mined from real repositories
            </div>
            <h2 className="search-title">
              What are you <em>building?</em>
            </h2>
            <form className="glass search-box" onSubmit={onSubmit}>
              <span className="search-icon">🔍</span>
              <input
                id="search-input"
                autoComplete="off"
                placeholder="collaborative rich-text editor with comments…"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
              <button type="submit" className="btn btn-dark search-go">
                Find recipe
              </button>
            </form>
            <div className="chips">
              {CHIPS.map((c) => (
                <button
                  key={c.label}
                  className="glass chip"
                  onClick={() => {
                    setQuery(c.q);
                    runSearch(c.q);
                  }}
                >
                  {c.emoji} {c.label}
                </button>
              ))}
            </div>
          </div>
        </section>

        {/* RESULTS */}
        <section className={`view view-results ${view === "results" ? "is-active" : ""}`}>
          <div className="results-wrap">
            <button className="glass pill back-btn" onClick={() => setView("search")}>
              ← new search
            </button>
            {recipe ? <RecipeView recipe={recipe} /> : null}
            {notFound ? (
              <div className="glass empty" style={{ borderRadius: 20 }}>
                No mined recipe for that yet. Try “collab editor”, “kanban
                board”, “data grid”, or “auth flow”.
              </div>
            ) : null}
          </div>
        </section>
      </main>
    </>
  );
}

function RecipeView({ recipe }: { recipe: Recipe }) {
  return (
    <div>
      <div className="recipe-head">
        <span className="recipe-kicker">Recipe · {recipe.library}</span>
        <h2 className="recipe-title">
          {recipe.title} <em>{recipe.emphasis}</em>
        </h2>
        <p className="recipe-meta">
          Mined from {recipe.reposMined} repositories · {recipe.callSites} call
          sites · runners-up: {recipe.runnersUp}
        </p>
      </div>

      <div className="glass verify-banner" style={{ borderRadius: 16 }}>
        ✅{" "}
        <span>
          Every step below is <b>graph-verified</b> against real call sites —
          click any receipt to inspect the source. No guesses.
        </span>
      </div>

      {recipe.steps.map((step, i) => (
        <div key={step.name} className="glass step">
          <div className="step-head">
            <div className="step-name">
              <span className="step-num">{i + 1}</span>
              {step.name}
            </div>
            <span className={`freq ${step.level === "high" ? "freq-high" : "freq-warn"}`}>
              {step.level === "high" ? "✓ " : "⚠ "}
              {step.freq} repos
            </span>
          </div>
          {step.code ? <code>{step.code}</code> : null}
          {step.note ? <p className="step-note">{step.note}</p> : null}
          <div className="receipts">
            {step.receipts.map((r, ri) => (
              <a
                key={`${r.label}-${ri}`}
                className="receipt"
                href={r.url}
                target="_blank"
                rel="noreferrer"
              >
                {r.label}
              </a>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

