cd ~/entire-graph/integrations/recipe-finder && echo "=== CLI list ==="; node engine/cli.mjs list 2>&1 | head -15; echo; echo "=== graph adapter smoke test: run entire graph edges on THIS repo & parse ==="; node -e '
import("./engine/graph.mjs").then(async (g) => {
  const ok = await g.graphAvailable();
  console.log("graphAvailable:", ok);
  const edges = g.edges(process.cwd()+"/../..", ["IMPORTS"], {});
  console.log("IMPORTS edges parsed from entire-graph repo:", edges.length);
  const ext = edges.map(g.importedModule).filter(Boolean).filter(m=>!m.startsWith("."));
  const top = {};
  for (const m of ext) top[m]=(top[m]||0)+1;
  const ranked = Object.entries(top).sort((a,b)=>b[1]-a[1]).slice(0,5);
  console.log("top external imports:", JSON.stringify(ranked));
}).catch(e=>{console.error("ERR", e.message); process.exit(1)});
